import{_ as o,o as t,c as n,a2 as r}from"./chunks/framework.BOeh4kYD.js";const u=JSON.parse('{"title":"Agent 核心研究与竞品动态 · 2026-09-14","description":"2026-09-14 Agent 核心研究者、Runtime 项目与 CodeFlowMu 竞品双源监测日档。","frontmatter":{"title":"Agent 核心研究与竞品动态 · 2026-09-14","description":"2026-09-14 Agent 核心研究者、Runtime 项目与 CodeFlowMu 竞品双源监测日档。","outline":[2,3]},"headers":[],"relativePath":"zh/runtime/daily-intelligence/2026-09-14.md","filePath":"zh/runtime/daily-intelligence/2026-09-14.md","lastUpdated":1789345347000}'),a={name:"zh/runtime/daily-intelligence/2026-09-14.md"};function s(i,e,p,c,d,l){return t(),n("div",null,[...e[0]||(e[0]=[r('<h1 id="agent-核心研究与竞品动态-·-2026-09-14" tabindex="-1">Agent 核心研究与竞品动态 · 2026-09-14 <a class="header-anchor" href="#agent-核心研究与竞品动态-·-2026-09-14" aria-label="Permalink to &quot;Agent 核心研究与竞品动态 · 2026-09-14&quot;">​</a></h1><blockquote><p>Asia/Shanghai · 仅收录达到 meaningful new developments 阈值的公开技术与产品变化。</p></blockquote><p><a href="./">返回每日动态索引</a></p><h2 id="当日结论" tabindex="-1">当日结论 <a class="header-anchor" href="#当日结论" aria-label="Permalink to &quot;当日结论&quot;">​</a></h2><p>本日最强的共振是：<strong>生产级 Agent 正把“调度前判断”进一步拆成可观测的实时资源、Workspace/Run 所有权、Transport 合同与恢复边界。</strong> 一个 Provider 还能连、一个 Session 还能续、一个 Tool 名还存在，都不再足以证明“这一轮可以安全执行”。</p><h2 id="_1-yue-zhao-赵岳-anywhere-agents-并行调度开始读取-当前可用模型组额度-而不是失败后才发现资源已经耗尽" tabindex="-1">1. Yue Zhao（赵岳）/ anywhere-agents：并行调度开始读取“当前可用模型组额度”，而不是失败后才发现资源已经耗尽 <a class="header-anchor" href="#_1-yue-zhao-赵岳-anywhere-agents-并行调度开始读取-当前可用模型组额度-而不是失败后才发现资源已经耗尽" aria-label="Permalink to &quot;1. Yue Zhao（赵岳）/ anywhere-agents：并行调度开始读取“当前可用模型组额度”，而不是失败后才发现资源已经耗尽&quot;">​</a></h2><p><strong>状态：MERGED（commit 050ee0b）</strong></p><p>赵岳本人提交的 <a href="https://github.com/yzhao062/anywhere-agents/commit/050ee0bd91c5d05c28f6f6b7c196a8d222328a4b" target="_blank" rel="noreferrer"><code>050ee0b</code></a> 把 Agy 的 quota meter 真正接入 <code>prun</code> 调度。Agy 将 Gemini 与 Claude/GPT-OSS 分成两个独立额度组；此前 fan-out 不读取这份状态，真实 2026-09-11 七单元批次中，Claude 组的五小时桶耗尽后连续四个单元失败。</p><p>新逻辑在 dispatch 前读取 <code>agent-quota.py</code> 的 snapshot：使用一个组中最紧的 bucket 判断可用性；Claude/GPT 组为空而 Gemini 可用时自动换到 Gemini 默认模型；Gemini 为空则明确退出，不会未经授权反向升级到更贵/更稀缺的组。fallback 会写入 <code>MODEL-FALLBACK</code> 和实际 model ledger，不允许结果看起来像由原模型完成。它还处理了 snapshot TTL、reset time 已过、stale refresh、非有限数值与失败后强制刷新等细节。</p><p><strong>为什么重要：</strong> 资源调度正在从“Provider 报错后再 fallback”转向 <strong>pre-dispatch live capacity admission</strong>。同时它保留“未知 ≠ 空”的语义，读不到 fresh snapshot 时不会把未知误判为拒绝。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 多模型团队不必强行抹平模型差异；应把 <code>Role → Candidate Models → Live Capacity/Cost → Selected Model → Fallback Receipt</code> 作为可审计调度链。EVAL/Gatekeeper 可以继续使用高价值模型，而规模化 Worker 根据实时资源分流。</p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Would you persist the quota snapshot identity/age into each dispatch receipt so later evaluation can prove which live resource evidence selected the model?</em></p><h2 id="_2-openai-codex-agents-overview-已能直接创建并绑定新的-managed-worktree-session" tabindex="-1">2. OpenAI Codex：Agents Overview 已能直接创建并绑定新的 Managed Worktree Session <a class="header-anchor" href="#_2-openai-codex-agents-overview-已能直接创建并绑定新的-managed-worktree-session" aria-label="Permalink to &quot;2. OpenAI Codex：Agents Overview 已能直接创建并绑定新的 Managed Worktree Session&quot;">​</a></h2><p><strong>状态：MERGED（PR #45276）</strong></p><p>PR <a href="https://github.com/openai/codex/pull/45276" target="_blank" rel="noreferrer">#45276</a> 已合入。Codex 的 Agents Overview 现在可以从项目默认分支创建新的 managed worktree，并立即启动一个<strong>空白 Session</strong>绑定到该 checkout；不会给新 Session 自动发送第一轮消息，也不会中断已有 Agent。</p><p>值得注意的不是快捷键本身，而是边界处理：默认分支来自缓存的 remote <code>HEAD</code>，必要时才回退到 <code>main/master</code>；保留源 checkout 的本地编辑；继承已选择的 approval reviewer；Session 启动失败时，clean 且未认领的 worktree 会清理，已经需要保留的 checkout 则把路径明确报告给用户；创建期间还会暂停冲突动作，并在 reconnect 后清掉 pending creation state。</p><p><strong>为什么重要：</strong> Codex 的“Agent 概览”正在从 Session 列表升级成 <strong>Workspace + Session 生命周期管理面</strong>。Thread/Session 和 Worktree 开始结构化绑定，而不是由用户自己在外部 Git 命令里拼接。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 对多角色房间/Branch TASK 很有参考价值：<code>Workspace Creation → Session Binding → Approval Context → Ownership/Cleanup</code> 应是同一事务，但 Conversation history、Workspace identity 与授权继承仍应分别记录。</p><p><strong>值得互动：高。</strong> 技术切入：<em>Will managed-worktree creation eventually emit a durable lineage receipt binding source revision, new checkout identity, thread ID and inherited approval context?</em></p><h2 id="_3-ag2-mcp-server-的-http-transport-开始成为-运营者自己的合同-而不是悄悄继承依赖包默认值" tabindex="-1">3. AG2：MCP Server 的 HTTP Transport 开始成为“运营者自己的合同”，而不是悄悄继承依赖包默认值 <a class="header-anchor" href="#_3-ag2-mcp-server-的-http-transport-开始成为-运营者自己的合同-而不是悄悄继承依赖包默认值" aria-label="Permalink to &quot;3. AG2：MCP Server 的 HTTP Transport 开始成为“运营者自己的合同”，而不是悄悄继承依赖包默认值&quot;">​</a></h2><p><strong>状态：DRAFT / OPEN（PR #3252）</strong></p><p>Draft PR <a href="https://github.com/ag2ai/ag2/pull/3252" target="_blank" rel="noreferrer">#3252</a> 暴露了一个很重要的 MCP 运行边界：AG2 过去自己创建 streamable-HTTP session manager，却只允许配置 <code>stateless</code> 和 <code>json_response</code>，其余安全/生命周期行为由安装的 <code>mcp</code> 版本默认决定。</p><p>新 <code>TransportConfig</code> 提议显式拥有：MCP session idle timeout、max sessions、request body size、transport security、SSE retry interval 和 event store。它同时引入可选的 RFC 8707 token resource 校验，使一个为其他服务签发的 bearer token 不能直接用于当前 Agent Server。event store 则让断线客户端可以用 last-event id 恢复错过的事件。</p><p>作者特别指出：AG2 原先没有 DNS rebinding protection，而且运营者没有入口启用；<code>mcp</code> 2.2.0 又在同一个 2.x 范围内改变了 session timeout/cap 默认值，这意味着两个看似安装“同一 AG2 版本”的部署可能因为依赖小版本不同而出现不同 Runtime 行为。</p><p><strong>为什么重要：</strong> 这是典型的 <strong>Dependency Default ≠ Product Contract</strong>。长期 Agent 的 timeout、session cap、resumability、host/origin policy 都应被产品自己固定并可审计。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> Host 准入不应只测“能不能连 MCP”，还要读取/验证 Transport contract：session lifetime、body limit、origin/host policy、event replay、token audience/resource binding。</p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Would you expose a transport-contract digest in server metadata so clients can bind resumability/security assumptions to the exact runtime configuration they connected to?</em></p><h2 id="_4-paperclip-clean-machine-安装验收已把-api-key-用户-和-本地-cli-subscription-用户-拆成不同准入路径" tabindex="-1">4. Paperclip：Clean-machine 安装验收已把“API key 用户”和“本地 CLI subscription 用户”拆成不同准入路径 <a class="header-anchor" href="#_4-paperclip-clean-machine-安装验收已把-api-key-用户-和-本地-cli-subscription-用户-拆成不同准入路径" aria-label="Permalink to &quot;4. Paperclip：Clean-machine 安装验收已把“API key 用户”和“本地 CLI subscription 用户”拆成不同准入路径&quot;">​</a></h2><p><strong>状态：MERGED（PR #13372）</strong></p><p>PR <a href="https://github.com/paperclipai/paperclip/pull/13372" target="_blank" rel="noreferrer">#13372</a> 来自一个真实 nightly release gate 失败：全新 Docker 环境在 Onboarding 的 “Connect a model” 步骤卡死。API key 已经被 Provider 实时验证为有效，但 managed adoption 仍强制要求本地 Claude CLI hello probe；干净机器没有 CLI，因此用户无法完成第一位 Agent 的 hire。</p><p>合入后的语义更精确：<code>api_key</code> binding 在 adoption 时再次调用 Provider live endpoint 验证，不再强制要求本地 CLI；subscription 路径仍保留严格 hello probe。Paperclip 还为 release smoke 做了本地 HTTPS provider mock，只开放 <code>GET /v1/models</code>，其他 endpoint 全部 404，从而可以验证“安装包在 Provider 接受 credential 时确实能完成 onboarding”，又不把真实付费凭证塞进 CI。</p><p><strong>为什么重要：</strong> 这是安装交付成熟度的实质提升。一个真正可交付的数字员工产品不能把“Provider credential 有效”和“本机安装了对应 CLI”混成同一准入条件。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> Host/Provider admission 应拆分为 <code>Credential Validity</code>、<code>Required Local Runtime</code>、<code>Selected Execution Lane</code> 三个事实。不同 lane 只能验证自己真正需要的依赖。</p><p><strong>学习：非常高｜竞争风险：很高｜雷达判断：Paperclip 继续维持最高优先级，安装/首次运行成熟度上调。</strong></p><p><strong>值得互动：高。</strong> 技术切入：<em>Will onboarding eventually publish the selected execution-lane identity so later runs can prove whether they were admitted through API-key direct execution or a local subscription CLI?</em></p><h2 id="_5-paperclip-mention-心跳-run-可能把-别人的-run-写成当前-issue-的执行锁" tabindex="-1">5. Paperclip：@mention 心跳 Run 可能把“别人的 Run”写成当前 Issue 的执行锁 <a class="header-anchor" href="#_5-paperclip-mention-心跳-run-可能把-别人的-run-写成当前-issue-的执行锁" aria-label="Permalink to &quot;5. Paperclip：@mention 心跳 Run 可能把“别人的 Run”写成当前 Issue 的执行锁&quot;">​</a></h2><p><strong>状态：OPEN / NOT SAFE TO MERGE YET（PR #13374）</strong></p><p>PR <a href="https://github.com/paperclipai/paperclip/pull/13374" target="_blank" rel="noreferrer">#13374</a> 记录了一个很典型的多 Agent ownership bug：Issue 分配给 Agent B，但评论里 @mention Agent A 后，A 会启动 heartbeat run，且 <code>contextSnapshot.issueId</code> 指向该 Issue。如果此时 B 的 assignee wake 到来，旧逻辑可能把 A 的 Run 误认成该 Issue 的 active execution lock，把 A 的 <code>runId</code> 写进 <code>executionRunId</code>，从而阻塞真正的 B，最长约 30 分钟。</p><p>候选修复的核心是：legacy run 只有在 <code>legacyRun.agentId === issue.assigneeAgentId</code> 时才能被收养为 execution lock，并把同一条件放进数据库 update predicate，防止并发 reassignment 绕过检查。</p><p>但当前 PR <strong>还不能视为完成</strong>。review 已指出它附加的 10 分钟 stale-lock sweep 可能直接清锁而绕过 deferred-wake promotion，反而把后续工作永久留在 stranded 状态；同时缺少针对 ownership/race 的自动回归测试。因此只能把它当作真实事故证据和正确 ownership 方向，不能把整个 patch 当成成熟修复。</p><p><strong>为什么重要：</strong> <code>context points to issue</code> 绝不等于 <code>run owns issue</code>。跨 Agent 的 comment/watch/mention 很容易把“观察关联”误当成“执行所有权”。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> 多角色之间的 TASK/REPORT/提醒必须明确区分 <code>Referenced Object</code>、<code>Responsible Role</code>、<code>Execution Owner</code>、<code>Wake Recipient</code>。任何 lock/adoption 都必须以 Owner identity 为硬前置，而不是仅凭关联 ID。</p><p><strong>学习：非常高｜竞争风险：高｜雷达判断：提高 Paperclip cross-agent ownership / deferred-wake recovery 的观察权重。</strong></p><h2 id="_6-superset-本周正式更新把-subagent-层级、更多-agent、手机-review、host-更新和-automations-商业化-同时推入产品面" tabindex="-1">6. Superset：本周正式更新把“Subagent 层级、更多 Agent、手机 Review、Host 更新和 Automations 商业化”同时推入产品面 <a class="header-anchor" href="#_6-superset-本周正式更新把-subagent-层级、更多-agent、手机-review、host-更新和-automations-商业化-同时推入产品面" aria-label="Permalink to &quot;6. Superset：本周正式更新把“Subagent 层级、更多 Agent、手机 Review、Host 更新和 Automations 商业化”同时推入产品面&quot;">​</a></h2><p><strong>状态：MERGED / FORMAL WEEKLY CHANGELOG（PR #7507）</strong></p><p>Superset 的 <a href="https://github.com/superset-sh/superset/pull/7507" target="_blank" rel="noreferrer">2026-09-13 weekly changelog</a> 已合入并由团队审核。几项值得一起看：</p><ul><li>Claude Code / Codex 生成的 subagent 现在在 workspace row 中<strong>嵌套在 parent Agent 下方</strong>，可单独打开并实时跟踪 transcript；</li><li>Muse Code 与 Devin CLI 进入 built-in agent catalog，并支持 session resume / token history；</li><li>Published Pages 已能在 iOS 阅读和逐元素评论；</li><li>standalone CLI Host 的版本可在 App 内查看并由 owner 更新；</li><li>pinned-workspace Automation 可以继续自己的旧 Agent Session，而不是每次 occurrence 都新建一套；</li><li><strong>Automations 现在成为 Pro 功能</strong>：创建、运行、启用需要 Pro，阅读、暂停、删除仍可在 Free 使用；</li><li>Web billing 已能升级/取消 Pro，iOS paywall 直接链接过去。</li></ul><p>官方安装文档目前仍写明：macOS 正式支持，Linux x64 AppImage 为 experimental，<strong>Windows 尚不可用</strong>。</p><p><strong>为什么重要：</strong> Superset 的竞争形态已经从“多 coding-agent 桌面壳”扩展成 <strong>Agent catalog + parent/subagent topology + Host lifecycle + mobile review + recurring automation + subscription monetization</strong>。</p><p><strong>与 CodeFlowMu 的关系：</strong> 这与数字员工工作站越来越接近，但 CodeFlowMu 仍可以在 Role/Responsibility、FCoP 事实链、独立 EVAL、授权/恢复边界上做更强差异化。商业上，Superset 已经明确把 Automation 作为付费抓手，而不是只卖模型调用。</p><p><strong>学习：非常高｜竞争风险：非常高｜雷达判断：建议正式将 Superset 从“重点第二圈”提升到主雷达。</strong></p><p><strong>值得互动：非常高。</strong> 技术切入：<em>Now that subagents are first-class in the UI, will their parentage also become a durable execution/audit identity rather than only a presentation hierarchy?</em></p><h2 id="_7-openai-agents-sdk-python-clear-session-清掉历史后-旧-response-compaction-chain-仍可能-穿回来" tabindex="-1">7. OpenAI Agents SDK Python：<code>clear_session()</code> 清掉历史后，旧 Response/Compaction Chain 仍可能“穿回来” <a class="header-anchor" href="#_7-openai-agents-sdk-python-clear-session-清掉历史后-旧-response-compaction-chain-仍可能-穿回来" aria-label="Permalink to &quot;7. OpenAI Agents SDK Python：`clear_session()` 清掉历史后，旧 Response/Compaction Chain 仍可能“穿回来”&quot;">​</a></h2><p><strong>状态：OPEN（PR #5000）</strong></p><p>PR <a href="https://github.com/openai/openai-agents-python/pull/5000" target="_blank" rel="noreferrer">#5000</a> 修复 <code>OpenAIResponsesCompactionSession.clear_session</code>：过去虽然底层 history 已清空，<code>_response_id</code> 与 <code>_last_unstored_response_id</code> 仍保留；后续 <code>run_compaction</code> 可能继续把这个旧 response id 传给 <code>responses.compact</code>，等于在“已清 Session”之后恢复引用被删除的 conversation chain。</p><p>候选修复让 <code>clear_session</code> 像此前的 <code>pop_item</code> 一样，同时失效 <code>_response_id</code>、<code>_deferred_response_id</code>、<code>_last_unstored_response_id</code>，包括 failed acknowledgement path。</p><p><strong>为什么重要：</strong> “删除历史”不能只删 visible items；所有能够把未来操作重新连接到旧世界的 continuation pointer / deferred pointer / response-chain identity 都必须一起失效。</p><p><strong>与 CodeFlowMu/FCoP 的关系：</strong> Reset/Archive/Forget/撤销操作应该拥有明确的 <strong>generation barrier</strong>。旧 checkpoint、provider continuation、pending retry、approval reference 只要仍能跨过 barrier，就不是真正的清除。</p><p><strong>值得互动：高。</strong> 技术切入：<em>Would it be safer to model session clear as a monotonic generation change so every continuation pointer carries the generation it belongs to and fails structurally after reset?</em></p><h2 id="跨项目共振" tabindex="-1">跨项目共振 <a class="header-anchor" href="#跨项目共振" aria-label="Permalink to &quot;跨项目共振&quot;">​</a></h2><p>本日可以归纳成一条很清楚的工程趋势：</p><blockquote><p><strong>长期 Agent 正从“保存状态”转向“保存带身份、时效、所有权和资源证据的状态”。</strong></p></blockquote><p>赵岳把 live quota snapshot 放到 dispatch 前；Codex 把 Worktree 与 Session 正式绑定；AG2 准备固定 MCP Transport 的安全与生命周期参数；Paperclip 把 Credential lane 与 CLI lane 分开，并暴露 cross-agent execution ownership bug；Agents SDK 则证明 reset 必须切断 continuation chain。</p><p>对 CodeFlowMu/FCoP，可以进一步固定这一链：</p><p><strong>Work/Run Identity → Workspace Identity → Responsible Owner → Live Capability/Capacity Evidence → Transport/Provider Contract → Call-time Admission → Effect → Settlement / Generation Barrier</strong>。</p><h2 id="双源核查说明" tabindex="-1">双源核查说明 <a class="header-anchor" href="#双源核查说明" aria-label="Permalink to &quot;双源核查说明&quot;">​</a></h2><p>本日同时检查了公开社交/官方项目页面与 GitHub 一手变更。Cursor 官方 Changelog 截至本轮仍以 9 月 10 日 Projects 为最近重大 Agent 架构更新，没有新的正式发布需要重复通知。公开社交搜索也没有找到 41 位名单中身份可可靠确认、且技术增量高于上述一手 GitHub/官方资料的本人新讨论，因此没有使用营销转发补数。</p>',67)])])}const h=o(a,[["render",s]]);export{u as __pageData,h as default};
